CardContent.displayName = 'CardContent';

const cardFooterVariants = cva('flex items-center [.border-t]:pt-6', {
  defaultVariants: {
    direction: 'row',
    gap: 'sm',
    justify: 'between',
    padding: 'none',
  },
  variants: {
    direction: {
      column: 'flex-col',
      row: 'flex-row',
    },
    gap: {
      lg: 'gap-6',
      md: 'gap-4',
      none: '',
      sm: 'gap-2',
    },
    justify: {
      around: 'justify-around',
      between: 'justify-between',
      center: 'justify-center',
      end: 'justify-end',
      start: 'justify-start',
    },
    padding: {
      lg: 'px-8',
      md: 'px-6',
      none: '',
      sm: 'px-3',
    },
  },
