CardForm.displayName = 'CardForm';

const cardFieldVariants = cva('flex flex-col', {
  defaultVariants: {
    spacing: 'normal',
  },
  variants: {
    spacing: {
      loose: 'space-y-2',
      normal: 'space-y-1.5',
